-- Catálogo colombiano de precios de BIMetrics.
-- Fuente: data/catalogo/catalogo_precios_colombia.csv
-- Motor destino: MySQL/MariaDB. Seleccione la base de datos antes de importar.
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS partidas (
  codigo VARCHAR(50) NOT NULL PRIMARY KEY,
  unidad VARCHAR(50) NOT NULL,
  descripcion TEXT NOT NULL,
  precio_defecto DECIMAL(14,2) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS variaciones_opciones (
  id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  codigo VARCHAR(50) NOT NULL,
  tipo VARCHAR(100) NOT NULL,
  opcion TEXT NULL,
  parametro VARCHAR(255) NULL,
  valor_probado VARCHAR(255) NULL,
  es_defecto TINYINT(1) NOT NULL DEFAULT 0,
  precio DECIMAL(14,2) NULL,
  INDEX ix_variaciones_opciones_codigo (codigo),
  CONSTRAINT fk_variaciones_opciones_partida FOREIGN KEY (codigo) REFERENCES partidas (codigo) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

